package telemetry

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/gofrs/uuid"
	"github.com/markphelps/flipt/config"
	"github.com/sirupsen/logrus"
	"github.com/stretchr/testify/require"
)

func testConfig(dir string) *config.Config {
	cfg := config.Default()
	cfg.Meta.StateDirectory = dir
	return cfg
}

func readState(t *testing.T, dir string) state {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(dir, stateFileName))
	require.NoError(t, err)
	var saved state
	require.NoError(t, json.Unmarshal(data, &saved))
	return saved
}

func TestNewReporterDisabled(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "state")
	cfg := testConfig(dir)
	cfg.Meta.TelemetryEnabled = false

	reporter, err := NewReporter(cfg, logrus.New())
	require.NoError(t, err)
	require.Nil(t, reporter)
	_, err = os.Stat(dir)
	require.True(t, os.IsNotExist(err))
}

func TestNewReporterCreatesAndReusesState(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "nested", "state")
	cfg := testConfig(dir)

	reporter, err := NewReporter(cfg, logrus.New())
	require.NoError(t, err)
	require.NotNil(t, reporter)
	saved := readState(t, dir)
	require.Equal(t, schemaVersion, saved.Version)
	_, err = uuid.FromString(saved.UUID)
	require.NoError(t, err)
	_, err = time.Parse(time.RFC3339, saved.LastTimestamp)
	require.NoError(t, err)

	again, err := NewReporter(cfg, logrus.New())
	require.NoError(t, err)
	require.Equal(t, saved, again.state)
	require.Equal(t, saved, readState(t, dir))
}

func TestNewReporterRepairsMalformedUUID(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, stateFileName)
	require.NoError(t, os.WriteFile(path, []byte(`{"version":"1.0","uuid":"bad","lastTimestamp":"2022-04-06T01:01:51Z"}`), 0600))

	reporter, err := NewReporter(testConfig(dir), logrus.New())
	require.NoError(t, err)
	saved := readState(t, dir)
	require.Equal(t, "2022-04-06T01:01:51Z", saved.LastTimestamp)
	require.Equal(t, saved.UUID, reporter.state.UUID)
	_, err = uuid.FromString(saved.UUID)
	require.NoError(t, err)
}

func TestNewReporterRejectsFileAsStateDirectory(t *testing.T) {
	path := filepath.Join(t.TempDir(), "state")
	require.NoError(t, os.WriteFile(path, []byte("leave alone"), 0600))

	reporter, err := NewReporter(testConfig(path), logrus.New())
	require.Error(t, err)
	require.Nil(t, reporter)
	data, err := os.ReadFile(path)
	require.NoError(t, err)
	require.Equal(t, "leave alone", string(data))
}

func TestReportSendsAnonymousEventAndUpdatesTimestamp(t *testing.T) {
	dir := t.TempDir()
	reporter, err := NewReporter(testConfig(dir), logrus.New())
	require.NoError(t, err)
	reporter.fliptVersion = "1.2.3"
	now := time.Date(2022, 4, 6, 5, 1, 51, 0, time.UTC)
	reporter.now = func() time.Time { return now }

	var received trackEvent
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.Header.Get("Content-Type") != "application/json" {
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		if err := json.NewDecoder(r.Body).Decode(&received); err != nil {
			w.WriteHeader(http.StatusBadRequest)
			return
		}
		w.WriteHeader(http.StatusAccepted)
	}))
	defer server.Close()
	reporter.endpoint = server.URL

	require.NoError(t, reporter.Report(context.Background()))
	require.Equal(t, "flipt.ping", received.Event)
	require.Equal(t, reporter.state.UUID, received.AnonymousID)
	require.Equal(t, received.AnonymousID, received.Properties.UUID)
	require.Equal(t, schemaVersion, received.Properties.Version)
	require.Equal(t, "1.2.3", received.Properties.Flipt.Version)
	require.Equal(t, now.Format(time.RFC3339), readState(t, dir).LastTimestamp)
}

func TestReportFailureKeepsTimestamp(t *testing.T) {
	dir := t.TempDir()
	reporter, err := NewReporter(testConfig(dir), logrus.New())
	require.NoError(t, err)
	previous := readState(t, dir)

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusInternalServerError)
	}))
	defer server.Close()
	reporter.endpoint = server.URL

	require.Error(t, reporter.Report(context.Background()))
	require.Equal(t, previous, readState(t, dir))
}

func TestStartReportsWhenDueAndStopsOnCancellation(t *testing.T) {
	reporter, err := NewReporter(testConfig(t.TempDir()), logrus.New())
	require.NoError(t, err)
	received := make(chan struct{}, 1)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		received <- struct{}{}
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()
	reporter.endpoint = server.URL

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan struct{})
	go func() {
		reporter.Start(ctx)
		close(done)
	}()

	select {
	case <-received:
	case <-time.After(5 * time.Second):
		t.Fatal("telemetry was not reported when due")
	}
	cancel()
	select {
	case <-done:
