func TestLoadMetaEnvironment(t *testing.T) {
	const telemetryKey = "FLIPT_META_TELEMETRY_ENABLED"
	const directoryKey = "FLIPT_META_STATE_DIRECTORY"

	previousTelemetry, hadTelemetry := os.LookupEnv(telemetryKey)
	previousDirectory, hadDirectory := os.LookupEnv(directoryKey)
	t.Cleanup(func() {
		if hadTelemetry {
			_ = os.Setenv(telemetryKey, previousTelemetry)
		} else {
			_ = os.Unsetenv(telemetryKey)
		}
		if hadDirectory {
			_ = os.Setenv(directoryKey, previousDirectory)
		} else {
			_ = os.Unsetenv(directoryKey)
		}
	})

	stateDirectory := t.TempDir()
	require.NoError(t, os.Setenv(telemetryKey, "false"))
	require.NoError(t, os.Setenv(directoryKey, stateDirectory))

	cfg, err := Load("./testdata/default.yml")
	require.NoError(t, err)
	assert.False(t, cfg.Meta.TelemetryEnabled)
	assert.Equal(t, stateDirectory, cfg.Meta.StateDirectory)

	require.NoError(t, os.Setenv(telemetryKey, "true"))
	cfg, err = Load("./testdata/advanced.yml")
	require.NoError(t, err)
	assert.True(t, cfg.Meta.TelemetryEnabled)
	assert.Equal(t, stateDirectory, cfg.Meta.StateDirectory)
}

